def sync_and_slice_intermediate_tensors(
    self,
    num_tokens: int,
    intermediate_tensors: IntermediateTensors | None,
    sync_self: bool,
) -> IntermediateTensors:
    assert self.intermediate_tensors is not None
    tp = self.vllm_config.parallel_config.tensor_parallel_size

    if sync_self:
        assert intermediate_tensors is not None
        for k, v in intermediate_tensors.items():
            copy_len = (num_tokens + tp - 1) // tp if enable_sp() else num_tokens
            if k not in self.intermediate_tensors.tensors:
                base_tensor = self.intermediate_tensors["hidden_states"]
                self.intermediate_tensors[k] = v.new_empty(
                    (base_tensor.shape[0], *v.shape[1:])
                )
            self.intermediate_tensors[k][:copy_len].copy_(
                v[:copy_len], non_blocking=True
            )

    return IntermediateTensors(
        {
            k: v[: (num_tokens + tp - 1) // tp]
            if enable_sp()
            else v[:num_tokens]
            for k, v in self.intermediate_tensors.items()
        }
    )

def sync_and_gather_intermediate_tensors(
    self,
    num_tokens: int,
    intermediate_tensors: IntermediateTensors | None,
    sync_self: bool,
) -> IntermediateTensors:
    # vLLM renamed sync_and_slice to sync_and_gather.
    return self.sync_and_slice_intermediate_tensors(
        num_tokens, intermediate_tensors, sync_self
    )

def sync_and_gather_intermediate_tensors(
    self,
    num_tokens: int,
    intermediate_tensors: IntermediateTensors | None,
    sync_self: bool,
) -> IntermediateTensors:
    assert self.intermediate_tensors is not None

    tp = self.vllm_config.parallel_config.tensor_parallel_size
    is_rs = is_residual_scattered_for_sp(self.vllm_config, num_tokens)

    # When sequence parallelism is enabled, the "residual" tensor is
    # sharded across TP ranks. All-gather it here because downstream
    # QKV + Attention needs the full residual before the SP split point.
    if sync_self:
        assert intermediate_tensors is not None
        for k, v in intermediate_tensors.items():
            is_scattered = k == "residual" and is_rs
            if is_scattered:
                local_len = num_tokens // tp
                v = get_tp_group().all_gather(v[:local_len], dim=0)

            self.intermediate_tensors[k][:num_tokens].copy_(
                v[:num_tokens], non_blocking=True
            )

    return IntermediateTensors(
        {k: v[:num_tokens] for k, v in self.intermediate_tensors.items()}
    )

def execute_model(
    self,
    scheduler_output: "SchedulerOutput",
) -> ModelRunnerOutput | AsyncModelRunnerOutput | None:
    self.log_memory_stats()
    # enable msMonitor to monitor the performance of vllm-ascend
    if get_ascend_config().msmonitor_use_daemon:
        dp.step()

    if self._pp_send_work:
        for handle in self._pp_send_work:
            handle.wait()
        self._pp_send_work = []

    intermediate_tensors = None
    forward_pass = scheduler_output.total_num_scheduled_tokens > 0
    if forward_pass and not get_pp_group().is_first_rank:
        if enable_sp():
            all_gather_group = None
        else:
            all_gather_group = get_tp_group()
        tensor_dict, comm_handles, comm_postprocess = get_pp_group().irecv_tensor_dict(
            all_gather_group=all_gather_group
        )
        assert tensor_dict is not None
        intermediate_tensors = AsyncIntermediateTensors(
            tensor_dict,
            comm_handles=comm_handles,
            comm_postprocess=comm_postprocess,
        )

    if self.profiler is not None:
        self.profiler.step()

    output = self.model_runner.execute_model(scheduler_output, intermediate_tensors)
    if isinstance(output, (ModelRunnerOutput, AsyncModelRunnerOutput, NoneType)):
        return output

    assert isinstance(output, IntermediateTensors)
    parallel_config = self.vllm_config.parallel_config
    assert parallel_config.distributed_executor_backend != ("external_launcher") and not get_pp_group().is_last_rank
    if enable_sp():
        all_gather_group = None
    else:
        all_gather_group = get_tp_group()
    self._pp_send_work = get_pp_group().isend_tensor_dict(
        output.tensors,
        all_gather_group=all_gather_group,
    )

    # Align with upstream GPUWorker: Model Runner V2 has no
    # kv_connector_output to propagate from non-last PP ranks. Model Runner
    # V1 must continue below to handle the PP + KV connector path.
    if self.use_v2_model_runner:
        return None

    kv_connector_output = output.kv_connector_output
    if not kv_connector_output:
        return None

    # In case of PP with kv transfer, we need to pass through the
    # kv_connector_output
    if not kv_connector_output.finished_sending and not kv_connector_output.finished_recving:
        return EMPTY_MODEL_RUNNER_OUTPUT
    output = copy.copy(EMPTY_MODEL_RUNNER_OUTPUT)
    output.kv_connector_output = kv_connector_output
    return output
